Task: Put the red cube into the red tray and the blue cube into the blue tray.

Skill code (numbered):
  1| import math
  2| 
  3| def run(robot):
  4|     """Sort cubes by colour into matching trays."""
  5|     robot.home()
  6| 
  7|     # Get current scene description
  8|     obs = robot.observe()
  9| 
 10|     # Separate cubes and trays
 11|     cubes = {name: obj for name, obj in obs['objects'].items() if obj['shape'] == 'cube'}
 12|     trays = {name: fix for name, fix in obs['fixtures'].items() if fix['kind'] == 'tray'}
 13| 
 14|     # Map colour -> tray name (e.g., 'red' -> 'red_tray')
 15|     colour_to_tray = {}
 16|     for name, fix in trays.items():
 17|         colour_to_tray[fix['color']] = name
 18| 
 19|     overall_success = True
 20| 
 21|     for cube_name, cube in cubes.items():
 22|         # Ensure a clean gripper before attempting the next pick
 23|         if robot.holding() is not None:
 24|             robot.release()
 25| 
 26|         colour = cube['color']
 27|         tray_name = colour_to_tray.get(colour)
 28|         if tray_name is None:
 29|             robot.log(f"No tray found for colour '{colour}'")
 30|             overall_success = False
 31|             continue
 32| 
 33|         # Get up-to-date poses (perception is noisy)
 34|         cube_pose = robot.get_pose(cube_name)
 35| 
 36|         if not _pick_and_place(robot, cube_pose, tray_name):
 37|             robot.log(f"Failed to place {cube_name} into {tray_name}")
 38|             overall_success = False
 39| 
 40|     return overall_success
 41| 
 42| 
 43| def _pick_and_place(robot, cube_pose, tray_name):
 44|     """Attempt one pick‑and‑place cycle. Returns True on success."""
 45|     max_attempts = 2
 46|     lift_height = 0.10          # safe travel height above the table
 47|     grasp_offset = 0.02         # how far above the cube centre we close the fingers
 48|     place_offset = 0.02         # how far above the tray bottom we release
 49| 
 50|     for attempt in range(max_attempts):
 51|         try:
 52|             # 1. Move above the cube
 53|             above_cube = [cube_pose['pos'][0], cube_pose['pos'][1], lift_height]
 54|             robot.move_to(*above_cube, speed=0.2)
 55| 
 56|             # 2. Descend to a grasp height (just above the cube centre)
 57|             # Clamp grasp_z to be at least 0.05 m above the cube centre to avoid table collisions
 58|             grasp_z = max(cube_pose['pos'][2] + grasp_offset,
 59|                           cube_pose['pos'][2] + 0.05)
 60|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], grasp_z,
 61|                           speed=0.05)
 62| 
 63|             # 3. Close fingers
 64|             if not robot.grasp():
 65|                 robot.release()  # ensure hand is open before retrying
 66|                 continue
 67| 
 68|             # 4. Verify we actually hold something
 69|             if robot.holding() is None:
 70|                 robot.release()
 71|                 continue
 72| 
 73|             # 5. Lift the cube
 74|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], lift_height,
 75|                           speed=0.05)
 76| 
 77|             # 6. Move above the target tray (use fresh tray pose to account for any drift)
 78|             tray_pose = robot.get_pose(tray_name)
 79|             above_tray = [tray_pose['pos'][0], tray_pose['pos'][1], lift_height]
 80|             robot.move_to(*above_tray, speed=0.2)
 81| 
 82|             # 7. Lower to just above the tray bottom
 83|             place_z = tray_pose['pos'][2] + place_offset
 84|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], place_z,
 85|                           speed=0.05)
 86| 
 87|             # 8. Release the cube
 88|             robot.release()
 89|             robot.wait(0.05)  # brief pause to let the object settle
 90| 
 91|             # 9. Retract to safe height
 92|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], lift_height,
 93|                           speed=0.05)
 94| 
 95|             return True  # success for this cube
 96| 
 97|         except Exception as e:  # catches MotionError and other unexpected issues
 98|             robot.log(f"Attempt {attempt+1} failed: {e}")
 99|             robot.release()  # try to leave the hand open
100|             continue
101| 
102|     # If we exit the loop, all attempts failed
103|     return False

